void CatalogFeeds::registerRoutes(httplib::Server& svr, std::shared_ptr<AuthenticationManager> auth)
{
    svr.Get("/catalogs/feeds/{feed_id}/processing_results", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleCatalogsfeedsfeedIdprocessingResultsGetRequest(req, res, auth);
    });
    svr.Post("/catalogs/feeds", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleCatalogsfeedsPostRequest(req, res, auth);
    });
    svr.Delete("/catalogs/feeds/{feed_id}", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleCatalogsfeedsfeedIdDeleteRequest(req, res, auth);
    });
    svr.Get("/catalogs/feeds/{feed_id}", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleCatalogsfeedsfeedIdGetRequest(req, res, auth);
    });
    svr.Post("/catalogs/feeds/{feed_id}/ingest", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleCatalogsfeedsfeedIdingestPostRequest(req, res, auth);
    });
    svr.Get("/catalogs/feeds", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleCatalogsfeedsGetRequest(req, res, auth);
    });
    svr.Patch("/catalogs/feeds/{feed_id}", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleCatalogsfeedsfeedIdPatchRequest(req, res, auth);
    });
    svr.Get("/catalogs/processing_results/{processing_result_id}/item_issues", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleCatalogsprocessingResultsprocessingResultIditemIssuesGetRequest(req, res, auth);
    });
}

